<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {useRouter} from 'vue-router'
import {api} from '../lib/api.js'
import {session} from '../lib/session.js'
import {currentMonth,shiftMonth,monthRange,money,budgetText,pct,categoryTone} from '../lib/format.js'
import {trendOption,pieOption} from '../lib/charts.js'
import Chart from '../components/Chart.vue'
import StateBox from '../components/StateBox.vue'
import AppIcon from '../components/AppIcon.vue'
const router=useRouter(),month=ref(currentMonth()),loading=ref(false),error=ref(''),summary=ref({income:0,expense:0,balance:0}),budget=ref(null),trends=ref([]),stats=ref([]),rows=ref([]),categories=ref([]),alerts=ref(0);let serial=0
const names=computed(()=>Object.fromEntries(categories.value.map(c=>[c.id,c.name]))),trend=computed(()=>trendOption(trends.value)),pie=computed(()=>pieOption(stats.value))
async function load(){if(!month.value)return;const n=++serial;loading.value=true;error.value='';try{const [from,to]=monthRange(month.value);const [s,b,t,c,r,cs,a]=await Promise.all([api.get('/statistics/summary',{params:{month:month.value}}),api.get(`/budgets/${month.value}`),api.get('/statistics/trends',{params:{from:shiftMonth(month.value,-5),to:month.value}}),api.get('/statistics/categories',{params:{month:month.value}}),api.get('/bills',{params:{from,to,size:5}}),api.get('/categories'),api.get('/alerts',{params:{size:1}})]);if(n===serial){summary.value=s;budget.value=b;trends.value=t;stats.value=c;rows.value=r.records;categories.value=cs;alerts.value=a.total}}catch(e){if(n===serial)error.value=e.message}finally{if(n===serial)loading.value=false}}
onMounted(load);watch(month,load)
</script><template><div class="view-toolbar"><span class="welcome-text">你好，{{session.user?.displayName||'朋友'}} <span class="wave-dot"></span> 这是你的月度账本</span><el-date-picker v-model="month" type="month" format="YYYY年MM月" value-format="YYYY-MM" :clearable="false" aria-label="总览月份"/></div><div v-loading="loading"><StateBox :error="error" @retry="load"><div class="metrics"><article class="metric-card"><span class="metric-caption">本月支出 <span class="metric-icon orange"><AppIcon name="BottomLeft"/></span></span><strong data-testid="overview-expense">{{money(summary.expense)}}</strong><small>记录每一笔生活开销</small></article><article class="metric-card"><span class="metric-caption">本月收入 <span class="metric-icon green"><AppIcon name="TopRight"/></span></span><strong data-testid="overview-income">{{money(summary.income)}}</strong><small>每一份收获，都值得记录</small></article><article class="metric-card"><span class="metric-caption">本月结余 <span class="metric-icon blue"><AppIcon name="Coin"/></span></span><strong data-testid="overview-balance">{{money(summary.balance)}}</strong><small>收入 − 支出</small></article><article class="metric-card accent"><span class="metric-caption">预算剩余 <span class="metric-icon"><AppIcon name="Wallet"/></span></span><strong>{{budget?.amount?money(budget.remaining):'尚未设置'}}</strong><small>{{budget?.amount?'本月预算 '+money(budget.amount):'为这个月，定一个小计划'}}</small></article></div><div class="dashboard-charts"><section class="panel"><div class="panel-heading"><div><h2>收支趋势</h2><p>最近6个月 · 单位：元</p></div><router-link to="/analysis" class="text-link">查看分析 <AppIcon name="ArrowRight" :size="12"/></router-link></div><Chart :option="trend" label="最近六个月收入和支出的折线趋势图" :height="275"/></section><section class="panel"><div class="panel-heading"><div><h2>支出去向</h2><p>本月消费分类占比</p></div><span class="subtle-label">{{stats.length}}个类别</span></div><StateBox :empty="!stats.length" title="本月还没有支出" description="记录支出后，即可查看分类占比。"><Chart :option="pie" label="本月各消费类别占比环形饼图" :height="275"/></StateBox></section></div><div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>最近账单</h2><p>所选月份的最近5笔记录</p></div><router-link to="/bills" class="text-link">全部账单 <AppIcon name="ArrowRight" :size="12"/></router-link></div><StateBox v-if="!rows.length" :empty="true"><el-button type="primary" plain @click="router.push({path:'/bills',query:{new:'1'}})">记第一笔</el-button></StateBox><div class="recent-list"><div v-for="r in rows" :key="r.id" class="recent-row"><span class="category-icon" :class="categoryTone(names[r.categoryId])"><AppIcon :name="r.type==='INCOME'?'TopRight':'ShoppingBag'" :size="18"/></span><div class="recent-description"><b>{{r.description}}</b><small>{{names[r.categoryId]}} <span>·</span> {{r.billDate}}</small></div><strong :class="{income:r.type==='INCOME'}">{{r.type==='INCOME'?'+':'−'}}{{money(r.amount)}}</strong></div></div></section><div><section class="panel compact-budget"><div class="panel-heading"><h2>预算进度</h2><router-link to="/budget" class="text-link">管理</router-link></div><template v-if="budget?.amount"><div class="budget-mini-number">{{budget.usageRate}}<span>% 已使用</span></div><el-progress :percentage="pct(budget.usageRate)" :show-text="false" :stroke-width="8" :color="budget.status==='EXCEEDED'?'#c6744e':'#287b63'"/><p class="muted small">已支出 {{money(budget.spent)}} / {{money(budget.amount)}}</p><div class="mini-note" :class="{warning:budget.status!=='NORMAL'}">{{budgetText(budget)}}</div></template><template v-else><p class="muted">设定一个月度预算，及时了解支出进度。</p><el-button type="primary" plain @click="router.push('/budget')">设置月度预算</el-button></template></section><router-link to="/alerts" class="alert-shortcut"><span class="category-icon orange"><AppIcon name="Bell"/></span><div><b>{{alerts?`${alerts}笔支出值得留意`:'暂时没有异常提醒'}}</b><small>基于个人历史消费的统计分析</small></div><AppIcon name="ArrowRight" :size="16"/></router-link></div></div></StateBox></div></template>
